import torch
import numpy as np

def run(x, mean, std):
    return x.log_normal_(mean, std)

def valid(ref_outputs, sol_outputs, inputs, ctx):
    out = sol_outputs[0] if isinstance(sol_outputs, (list, tuple)) else sol_outputs
    out = out.to(torch.float32)
    mean = float(ctx.get('mean', 1.0))
    std = float(ctx.get('std', 2.0))
    if not bool((out > 0).all()):
        return {'passed': False, 'message': 'log_normal_ output has non-positive values', 'metrics': {}}
    expected_mean = float(np.exp(mean + std ** 2 / 2))
    got_mean = float(out.mean())
    tol = 0.15 * expected_mean
    ok = abs(got_mean - expected_mean) <= tol
    return {'passed': bool(ok), 'message': 'ok' if ok else 'mean out of tolerance', 'metrics': {'got_mean': got_mean, 'expected_mean': expected_mean, 'tol': tol}}
